const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#16385C','#4DC6D8','#FFF3C4','#FF7C63','#37A66A'], background:'#4DC6D8', seed:481516
});

const C={navy:'#16385C',water:'#4DC6D8',cream:'#FFF3C4',coral:'#FF7C63',green:'#37A66A',road:'#F8E7B9',ink:'#16385C'};
const stops=[
  {name:'Lighthouse Café',color:'#FF7C63',parcel:{x:132,y:280},target:{x:805,y:118},icon:'☕'},
  {name:'Coral Market',color:'#37A66A',parcel:{x:132,y:280},target:{x:806,y:423},icon:'M'},
  {name:'Seabreeze Hotel',color:'#4DC6D8',parcel:{x:132,y:280},target:{x:805,y:270},icon:'H'}
];
const blocks=[
  {x:347,y:92,w:272,h:288,label:'Harbor Houses',color:'#FFB18B'},
  {x:104,y:90,w:158,h:104,label:'Post Office',color:'#FFF3C4'},
  {x:700,y:185,w:135,h:118,label:'Marina Hall',color:'#FFE29A'},
  {x:92,y:398,w:170,h:66,label:'Boat Shed',color:'#FF9B82'}
];
function circleBlock(x,y,r,b){const qx=Math.max(b.x,Math.min(x,b.x+b.w));const qy=Math.max(b.y,Math.min(y,b.y+b.h));return (x-qx)*(x-qx)+(y-qy)*(y-qy)<r*r;}
function driving(input){return !!(input.keys.ArrowLeft||input.keys.ArrowRight||input.keys.ArrowUp||input.keys.ArrowDown||input.keys.KeyA||input.keys.KeyD||input.keys.KeyW||input.keys.KeyS||input.keys.Space||input.pointer.down);}

const play={
  init(){this.run=0;},
  reset(){
    this.run=(this.run||0)+1;
    this.p={x:76,y:280,vx:0,vy:0,a:0};
    this.delivery=0;this.carry=false;this.timer=75;this.blocked=false;this.path=[];this.pathAt=0;
    this.notice='Drive to the parcel crate';this.noticeT=3;this.pickupGate=1.42;this.soundClock=0;this.lastX=0;this.lastY=0;
    if(this.run>1) game.event('fresh_run_started',{run:this.run});
  },
  makeReturnPath(){
    if(this.delivery===0) return [];
    return [{x:665,y:470},{x:292,y:470},{x:132,y:280}];
  },
  makeDetour(s){return [{x:300,y:465},{x:652,y:465},{x:s.target.x,y:s.target.y}];},
  goal(){
    const s=stops[this.delivery];
    if(!s)return {x:480,y:270};
    if(this.pathAt<this.path.length)return this.path[this.pathAt];
    return this.carry?s.target:s.parcel;
  },
  advancePath(){
    const g=this.goal(),p=this.p;
    if(this.pathAt<this.path.length && GF.math.dist(p.x,p.y,g.x,g.y)<28)this.pathAt++;
  },
  update(dt){
    const s=stops[this.delivery];if(!s)return;
    const active=driving(game.input);
    this.timer=Math.max(0,this.timer-dt*(active?1:6));
    this.noticeT=Math.max(0,this.noticeT-dt);
    this.soundClock+=dt;
    if(active&&this.soundClock>.72){this.soundClock=0;GF.Sfx.beep({freq:150,to:175,dur:.055,type:'triangle',vol:.035});}
    if(this.timer<15&&Math.floor((this.timer+dt)*2)!==Math.floor(this.timer*2))GF.Sfx.beep({freq:760,dur:.035,type:'square',vol:.1});
    if(this.timer<=0){game.flash('#FF7C63',.4);game.shake(6,.28);GF.Sfx.noise({dur:.28,vol:.18,freq:240});game.gameOver({message:"TIME'S UP — DISPATCH MISSED"});return;}

    if(!this.carry&&this.path.length===0&&this.delivery>0){this.path=this.makeReturnPath();this.pathAt=0;}
    if(active){
      this.advancePath();
      const g=this.goal(),p=this.p;let dx=g.x-p.x,dy=g.y-p.y,dl=Math.hypot(dx,dy)||1;
      dx/=dl;dy/=dl;
      const speed=650;
      p.vx+=(dx*speed-p.vx)*Math.min(1,dt*8);p.vy+=(dy*speed-p.vy)*Math.min(1,dt*8);
    }else{this.p.vx*=Math.max(0,1-dt*5);this.p.vy*=Math.max(0,1-dt*5);}
    const p=this.p,ox=p.x,oy=p.y;p.x+=p.vx*dt;p.y+=p.vy*dt;
    let hit=false;
    for(const b of blocks){if(circleBlock(p.x,p.y,13,b)){hit=true;break;}}
    if(hit){
      p.x=ox;p.y=oy;p.vx=0;p.vy=0;
      if(this.carry&&!this.blocked){this.blocked=true;this.path=this.makeDetour(s);this.pathAt=0;this.notice='Street blocked — take the waterfront lane!';this.noticeT=1.6;}
      GF.Sfx.beep({freq:170,to:120,dur:.075,type:'square',vol:.1});
    }
    p.x=GF.math.clamp(p.x,28,932);p.y=GF.math.clamp(p.y,72,510);
    const vl=Math.hypot(p.vx,p.vy);if(vl>10)p.a=Math.atan2(p.vy,p.vx);
    if(vl>250&&(this.lastX*p.vx+this.lastY*p.vy)<-35000){game.burst(p.x,p.y,{count:4,speed:38,size:2,life:.25,colors:[C.cream],gravity:35});}
    this.lastX=p.vx;this.lastY=p.vy;

    if(!this.carry&&game.time>this.pickupGate&&GF.math.dist(p.x,p.y,s.parcel.x,s.parcel.y)<32){
      this.carry=true;this.path=[];this.pathAt=0;this.blocked=false;game.addScore(25);
      this.notice='Parcel aboard! Follow the matching beacon.';this.noticeT=2;
      game.event('parcel_collected',{stop:this.delivery+1,before:game.score-25,after:game.score});
      game.event('courier_scooter_delivery_started',{stop:this.delivery+1,target:s.name});
      game.burst(p.x,p.y,{count:12,speed:85,size:3,life:.46,colors:[s.color,C.cream],gravity:85});
      GF.Sfx.beep({freq:480,to:720,dur:.14,type:'triangle',vol:.22});
    }
    if(this.carry&&GF.math.dist(p.x,p.y,s.target.x,s.target.y)<43)this.finish(s);
  },
  finish(s){
    const before=game.score;game.addScore(100);this.carry=false;this.delivery++;
    game.shake(4,.16);game.flash(s.color,.35);game.hitStop(.08);
    game.burst(s.target.x,s.target.y,{count:28,speed:160,size:4,life:.8,colors:[s.color,C.cream,C.green,C.coral],gravity:160});
    GF.Sfx.noise({dur:.1,vol:.15,freq:900});GF.Sfx.melody([[660,.08],[880,.1],[1100,.16]],{type:'triangle',vol:.18});
    game.event('delivery_completed',{stop:this.delivery,name:s.name,before:before,after:game.score});
    if(this.blocked)game.event('route_detour_completed',{stop:this.delivery,route:'waterfront_lane'});
    if(this.delivery>=3){game.event('third_delivery_completed',{deliveries:3,timerRemaining:Math.ceil(this.timer)});game.win({message:'ALL THREE DELIVERIES COMPLETE!'});return;}
    this.path=[];this.pathAt=0;this.timer=Math.min(75,this.timer+4);this.notice='Delivered! +4 tide-clock seconds';this.noticeT=2;
  },
  draw(ctx){
    const W=960,H=540,t=game.time;
    const sea=ctx.createLinearGradient(0,0,W,H);sea.addColorStop(0,'#83E0E5');sea.addColorStop(1,C.water);ctx.fillStyle=sea;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.3;ctx.strokeStyle='#FFF3C4';ctx.lineWidth=2;
    for(let y=40;y<H;y+=35){ctx.beginPath();for(let x=0;x<W;x+=45)ctx.quadraticCurveTo(x+22,y+4*Math.sin((x+y+t*18)/55),x+45,y);ctx.stroke();}ctx.globalAlpha=1;
    ctx.fillStyle=C.road;ctx.fillRect(45,58,850,430);ctx.fillStyle='#FFF9E5';ctx.fillRect(56,69,828,408);
    ctx.strokeStyle='#D6B875';ctx.lineWidth=3;ctx.setLineDash([10,10]);ctx.beginPath();ctx.moveTo(280,76);ctx.lineTo(280,470);ctx.moveTo(68,330);ctx.lineTo(875,330);ctx.stroke();ctx.setLineDash([]);
    for(const b of blocks){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,14,'rgba(22,56,92,.22)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,14,b.color);ctx.fillStyle='rgba(255,255,255,.4)';ctx.fillRect(b.x+13,b.y+13,b.w-26,10);GF.Draw.text(ctx,b.label,b.x+b.w/2,b.y+b.h/2,{size:14,color:C.ink,weight:'800'});}
    for(let i=0;i<stops.length;i++){const s=stops[i],on=i===this.delivery;ctx.globalAlpha=on?1:.4;ctx.strokeStyle=s.color;ctx.lineWidth=on?5:3;ctx.beginPath();ctx.arc(s.target.x,s.target.y,on?32:23,0,Math.PI*2);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.target.x,s.target.y,12,0,Math.PI*2);ctx.fill();GF.Draw.text(ctx,s.icon,s.target.x,s.target.y+1,{size:13,color:'#fff'});if(on)GF.Draw.text(ctx,s.name,s.target.x,s.target.y-43,{size:14,color:C.ink,weight:'800'});ctx.globalAlpha=1;}
    const s=stops[this.delivery];if(s&&!this.carry){const q=s.parcel,sc=1+Math.sin(t*6)*.1;ctx.save();ctx.translate(q.x,q.y);ctx.scale(sc,sc);GF.Draw.roundRect(ctx,-16,-12,32,24,4,s.color);ctx.fillStyle=C.cream;ctx.fillRect(-12,-3,24,4);ctx.restore();GF.Draw.text(ctx,'PARCEL',q.x,q.y-27,{size:12,color:C.ink});}
    if(s){const p=this.p,o=this.goal();let ax=o.x-p.x,ay=o.y-p.y,al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;const ex=480+ax*425,ey=285+ay*210;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(ex,ey,11+Math.sin(t*5)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(ex+ax*14,ey+ay*14);ctx.lineTo(ex-ay*8,ey+ax*8);ctx.lineTo(ex+ay*8,ey-ax*8);ctx.fill();}
    const p=this.p;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.fillStyle='rgba(22,56,92,.22)';ctx.beginPath();ctx.ellipse(-1,8,22,10,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-13,0);ctx.lineTo(14,0);ctx.stroke();ctx.fillStyle=C.navy;ctx.beginPath();ctx.arc(-12,0,7,0,Math.PI*2);ctx.arc(14,0,7,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-8,-10,23,18,7,C.water);ctx.fillStyle=C.cream;ctx.fillRect(7,-6,10,4);if(this.carry)GF.Draw.roundRect(ctx,-17,-13,13,12,2,s.color);ctx.restore();
    GF.Draw.roundRect(ctx,16,12,176,46,11,'rgba(22,56,92,.94)');GF.Draw.text(ctx,'TIDE-CLOCK',29,28,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,Math.ceil(this.timer)+'s',178,38,{size:25,color:this.timer<15?C.coral:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,650,12,294,46,11,'rgba(22,56,92,.94)');GF.Draw.text(ctx,'DELIVERY PROGRESS',665,28,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,this.delivery+' / 3',928,38,{size:23,color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,16,70,330,47,11,'rgba(22,56,92,.94)');GF.Draw.text(ctx,this.carry?'DELIVER TO':'PICK UP FOR',30,86,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,s?(this.carry?s.name:'Stop '+(this.delivery+1)+' • '+s.name):'',332,103,{size:17,color:s?s.color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,385,70,190,47,11,'rgba(22,56,92,.94)');GF.Draw.text(ctx,'SCORE',400,87,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,String(game.score),560,103,{size:22,color:'#fff',align:'right'});
    if(this.noticeT>0)GF.Draw.text(ctx,this.notice,480,510,{size:17,color:C.ink,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.15);
  }
};
game.add('play',play);
game.titleScreen({subtitle:'Arrow Keys / WASD drive • collect parcels • beat the tide-clock'});
